### game/src/state.js (77 lines, 2528 bytes)

```js
// NEON BASTION — the game state: gold, lives, score, waves, towers and enemies.
// One object holds a whole game; starting a new game means making a fresh one.

NB.newGame = function newGame() {
  return {
    screen: 'title', // title | playing | paused | victory | defeat
    gold: NB.CFG.startGold,
    lives: NB.CFG.startLives,
    score: 0,
    wave: 0,
    kills: 0,
    leaked: 0,
    time: 0,
    speed: 1,
    waveActive: false,
    spawnQueue: [],
    spawnTimer: 0,
    spawnGap: 0.55,
    towers: [], // {type, level, col, row, x, y, cooldown, angle, invested}
    enemies: [], // {type, hp, maxHp, x, y, wp, speed, slowUntil, slowPct, r, dist}
    projectiles: [],
    beams: [],
    particles: [],
    texts: [],
    shake: 0,
    selected: null, // {col, row} tower being inspected, or null
    buildType: null, // tower type the player is about to place, or null
    hover: null, // {col, row} grid cell under the mouse, or null
    banner: null, // {text, sub, until} big centre announcement
    waveCountdown: 0,
    best: 0,
    muted: false,
    stats: { earned: 0, spent: 0, built: 0, sold: 0 },
  };
};

// Grid helpers: pixel centre of a cell, and whether a cell can hold a tower.
NB.cellXY = function cellXY(col, row) {
  return { x: col * NB.CFG.cell + NB.CFG.cell / 2, y: NB.CFG.hudHeight + row * NB.CFG.cell + NB.CFG.cell / 2 };
};

NB.pathCells = function pathCells() {
  const cells = new Set();
  const pts = NB.CFG.path;
  for (let i = 0; i < pts.length - 1; i += 1) {
    let [x0, y0] = pts[i];
    const [x1, y1] = pts[i + 1];
    const dx = Math.sign(x1 - x0);
    const dy = Math.sign(y1 - y0);
    while (x0 !== x1 || y0 !== y1) {
      if (x0 >= 0 && x0 < NB.CFG.gridCols && y0 >= 0 && y0 < NB.CFG.gridRows) cells.add(`${x0},${y0}`);
      x0 += dx; y0 += dy;
    }
  }
  const last = pts[pts.length - 1];
  void last;
  return cells;
};
NB.PATH_SET = NB.pathCells();

NB.onPath = function onPath(col, row) { return NB.PATH_SET.has(`${col},${row}`); };

NB.towerAt = function towerAt(game, col, row) {
  return game.towers.find((t) => t.col === col && t.row === row) || null;
};

NB.canBuild = function canBuild(game, col, row) {
  if (col < 0 || col >= NB.CFG.gridCols || row < 0 || row >= NB.CFG.gridRows) return false;
  if (NB.onPath(col, row)) return false;
  if (NB.towerAt(game, col, row)) return false;
  return true;
};

// Waypoints in pixels, from the cell path (used by enemies).
NB.waypoints = function waypoints() {
  return NB.CFG.path.map(([c, r]) => NB.cellXY(c, r));
};
```

### game/src/enemies.js (132 lines, 4596 bytes)

```js
// NEON BASTION — enemies: spawning a wave, walking the path, taking damage,
// leaking into the Bastion. Bosses arrive on waves 5, 10 and 15.

NB.startWave = function startWave(game) {
  if (game.waveActive || game.wave >= NB.CFG.maxWaves) return false;
  game.wave += 1;
  const comp = NB.waveComp(game.wave);
  // Shuffle the spawn order (seeded when a shot scene sets the seed).
  for (let i = comp.length - 1; i > 0; i -= 1) {
    const j = Math.floor(NB.rand() * (i + 1));
    const tmp = comp[i]; comp[i] = comp[j]; comp[j] = tmp;
  }
  game.spawnQueue = comp;
  game.spawnTimer = 0.4;
  game.spawnGap = Math.max(0.28, 0.6 - game.wave * 0.015);
  game.waveActive = true;
  game.banner = { text: `WAVE ${game.wave}`, sub: game.wave % 5 === 0 ? 'WARDEN INBOUND' : `${comp.length} hostiles on the path`, until: game.time + 2.2 };
  NB.Audio.waveHorn();
  return true;
};

NB.spawnEnemy = function spawnEnemy(game, type) {
  const def = NB.ENEMIES[type];
  const hp = NB.enemyHp(type, game.wave);
  const start = NB.cellXY(NB.CFG.path[0][0], NB.CFG.path[0][1]);
  game.enemies.push({
    type, hp, maxHp: hp,
    x: start.x, y: start.y,
    wp: 1,
    speed: def.speed * NB.randRange(0.95, 1.05),
    slowUntil: 0, slowPct: 0,
    r: def.r,
    dist: 0,
    flash: 0,
    wobble: NB.rand() * Math.PI * 2,
  });
};

NB.updateEnemies = function updateEnemies(game, dt) {
  const wps = NB.waypoints();
  for (let i = game.enemies.length - 1; i >= 0; i -= 1) {
    const e = game.enemies[i];
    e.flash = Math.max(0, e.flash - dt * 6);
    // Slow wears off on its own clock.
    const slowed = game.time < e.slowUntil;
    const speed = e.speed * (slowed ? (1 - e.slowPct) : 1);
    let move = speed * dt;
    while (move > 0 && e.wp < wps.length) {
      const target = wps[e.wp];
      const dx = target.x - e.x;
      const dy = target.y - e.y;
      const d = Math.hypot(dx, dy);
      if (d <= move) {
        e.x = target.x; e.y = target.y;
        e.wp += 1; move -= d; e.dist += d;
      } else {
        e.x += (dx / d) * move; e.y += (dy / d) * move;
        e.dist += move; move = 0;
      }
    }
    if (e.wp >= wps.length) {
      // Reached the Bastion: it leaks, lives fall, the screen shakes.
      const def = NB.ENEMIES[e.type];
      game.lives -= def.lives;
      game.leaked += 1;
      game.shake = Math.max(game.shake, e.type === 'boss' ? 14 : 8);
      NB.Audio.leak();
      NB.addText(game, e.x - 20, e.y - 30, `-${def.lives} ♥`, '#ff5d7e');
      NB.burst(game, e.x, e.y, '#ff5d7e', 14);
      game.enemies.splice(i, 1);
      if (game.lives <= 0) {
        game.lives = 0;
        NB.endGame(game, false);
      }
    }
  }
  // Spawning trickles the queue in while the wave runs.
  if (game.waveActive && game.spawnQueue.length > 0) {
    game.spawnTimer -= dt;
    if (game.spawnTimer <= 0) {
      NB.spawnEnemy(game, game.spawnQueue.shift());
      game.spawnTimer = game.spawnGap;
    }
  }
  // Wave cleared when nothing is left to spawn or fight.
  if (game.waveActive && game.spawnQueue.length === 0 && game.enemies.length === 0) {
    game.waveActive = false;
    const bonus = NB.waveClearBonus(game.wave);
    game.gold += bonus;
    game.stats.earned += bonus;
    game.score += 100 * game.wave;
    game.banner = { text: 'WAVE CLEARED', sub: `+${bonus} gold bonus`, until: game.time + 2.0 };
    NB.Audio.coin();
    if (game.wave >= NB.CFG.maxWaves) NB.endGame(game, true);
  }
};

NB.damageEnemy = function damageEnemy(game, e, dmg) {
  e.hp -= dmg;
  e.flash = 1;
  if (e.hp <= 0) {
    const def = NB.ENEMIES[e.type];
    const idx = game.enemies.indexOf(e);
    if (idx !== -1) game.enemies.splice(idx, 1);
    game.gold += def.gold;
    game.stats.earned += def.gold;
    game.score += def.score + game.wave * 2;
    game.kills += 1;
    NB.addText(game, e.x, e.y - e.r - 6, `+${def.gold}`, '#ffd75e');
    NB.burst(game, e.x, e.y, def.color, e.type === 'boss' ? 40 : 12);
    if (e.type === 'boss') { game.shake = Math.max(game.shake, 12); NB.Audio.cannon(); }
    else NB.Audio.pop();
  }
};

NB.endGame = function endGame(game, won) {
  game.screen = won ? 'victory' : 'defeat';
  game.waveActive = false;
  game.banner = null;
  if (won) {
    const bonus = game.lives * 150;
    game.score += bonus;
    NB.Audio.victory();
  } else {
    NB.Audio.defeat();
  }
  try {
    const best = Number(window.localStorage.getItem('neon-bastion-best') || 0);
    if (game.score > best) window.localStorage.setItem('neon-bastion-best', String(game.score));
    game.best = Math.max(best, game.score);
  } catch (err) { game.best = game.score; }
};
```

### game/src/towers.js (91 lines, 2941 bytes)

```js
// NEON BASTION — towers: building, aiming, firing, upgrading and selling.
// A tower fires at the enemy furthest along the path inside its range.

NB.towerStats = function towerStats(type, level) {
  const def = NB.TOWERS[type];
  const lv = def.levels[level - 1];
  return {
    dmg: lv.dmg,
    rate: lv.rate,
    range: lv.range,
    splash: lv.splash !== undefined ? lv.splash : def.splash,
    slowPct: lv.slowPct !== undefined ? lv.slowPct : def.slowPct,
    slowSecs: def.slowSecs || 0,
  };
};

NB.buildTower = function buildTower(game, type, col, row) {
  const def = NB.TOWERS[type];
  if (!NB.canBuild(game, col, row)) { NB.Audio.error(); return false; }
  if (game.gold < def.cost) { NB.Audio.error(); return false; }
  const p = NB.cellXY(col, row);
  game.gold -= def.cost;
  game.stats.spent += def.cost;
  game.stats.built += 1;
  game.towers.push({
    type, level: 1, col, row, x: p.x, y: p.y,
    cooldown: 0, angle: -Math.PI / 2, invested: def.cost, placedAt: game.time,
  });
  NB.burst(game, p.x, p.y, def.color, 10);
  NB.Audio.upgrade();
  return true;
};

NB.upgradeTower = function upgradeTower(game, tower) {
  const def = NB.TOWERS[tower.type];
  if (tower.level >= 3) return false;
  const cost = def.levels[tower.level].upCost;
  if (game.gold < cost) { NB.Audio.error(); return false; }
  game.gold -= cost;
  game.stats.spent += cost;
  tower.invested += cost;
  tower.level += 1;
  NB.burst(game, tower.x, tower.y, def.color, 16);
  NB.Audio.upgrade();
  return true;
};

NB.sellTower = function sellTower(game, tower) {
  const refund = Math.floor(tower.invested * NB.CFG.sellRefund);
  game.gold += refund;
  game.towers.splice(game.towers.indexOf(tower), 1);
  NB.addText(game, tower.x, tower.y - 24, `+${refund}`, '#ffd75e');
  NB.Audio.coin();
  return refund;
};

// The target that has travelled furthest along the path and is in range.
NB.pickTarget = function pickTarget(game, tower, stats) {
  let best = null;
  for (const e of game.enemies) {
    const d = Math.hypot(e.x - tower.x, e.y - tower.y);
    if (d <= stats.range + e.r && (!best || e.dist > best.dist)) best = e;
  }
  return best;
};

NB.updateTowers = function updateTowers(game, dt) {
  for (const t of game.towers) {
    t.cooldown -= dt;
    const stats = NB.towerStats(t.type, t.level);
    const target = NB.pickTarget(game, t, stats);
    if (!target) continue;
    t.angle = Math.atan2(target.y - t.y, target.x - t.x);
    if (t.cooldown > 0) continue;
    t.cooldown = 1 / stats.rate;
    if (t.type === 'railgun') {
      NB.beam(game, t, target, stats);
      NB.damageEnemy(game, target, stats.dmg);
      NB.Audio.railgun();
    } else if (t.type === 'cannon') {
      NB.shell(game, t, target, stats);
      NB.Audio.cannon();
    } else if (t.type === 'frost') {
      NB.shard(game, t, target, stats);
      NB.Audio.frost();
    } else {
      NB.bolt(game, t, target, stats);
      NB.Audio.shoot();
    }
  }
};
```

### game/src/projectiles.js (108 lines, 4064 bytes)

```js
// NEON BASTION — projectiles, beams, explosions, particles and floating text.
// All the juice: nothing here changes the rules, it only shows them.

NB.bolt = function bolt(game, tower, target, stats) {
  game.projectiles.push({
    kind: 'bolt', x: tower.x, y: tower.y, target,
    speed: 520, dmg: stats.dmg, color: NB.TOWERS[tower.type].color, r: 4,
  });
};

NB.shard = function shard(game, tower, target, stats) {
  game.projectiles.push({
    kind: 'shard', x: tower.x, y: tower.y, target,
    speed: 420, dmg: stats.dmg, color: '#8fd8ff', r: 5,
    slowPct: stats.slowPct, slowSecs: stats.slowSecs,
  });
};

NB.shell = function shell(game, tower, target, stats) {
  game.projectiles.push({
    kind: 'shell', x: tower.x, y: tower.y,
    tx: target.x, ty: target.y, target,
    speed: 300, dmg: stats.dmg, splash: stats.splash, color: '#ffb02e', r: 7,
  });
};

// A railgun beam hits instantly and draws a fading lance for a few frames.
