NB.burst = function burst(game, x, y, color, count) {
  for (let i = 0; i < count; i += 1) {
    const a = NB.rand() * Math.PI * 2;
    const sp = NB.randRange(40, 180);
    game.particles.push({
      x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
